CREATE TABLE employees (id INTEGER PRIMARY KEY, name TEXT, position TEXT, manager_id INTEGER, hired TEXT);
CREATE TABLE clients (id INTEGER PRIMARY KEY, name TEXT, city TEXT, segment TEXT, registered TEXT);
CREATE TABLE products (id INTEGER PRIMARY KEY, name TEXT, category TEXT, price INTEGER);
CREATE TABLE orders (id INTEGER PRIMARY KEY, client_id INTEGER, employee_id INTEGER, order_date TEXT, status TEXT);
CREATE TABLE order_items (order_id INTEGER, product_id INTEGER, qty INTEGER, price INTEGER);
CREATE TABLE payments (id INTEGER PRIMARY KEY, order_id INTEGER, paid_date TEXT, amount INTEGER);
